#include <string>
#include <vector>
#include <algorithm>
#include <unordered_map>

class Solution {
public:
    int minDeletion(std::string s, int k) {
        std::unordered_map<char, int> cnt;
        for (char ch : s) cnt[ch]++;

        if ((int)cnt.size() <= k) return 0;

        std::vector<int> freqs;
        for (const auto& pair : cnt) {
            freqs.push_back(pair.second);
        }
        std::sort(freqs.begin(), freqs.end());

        int ans = 0;
        int to_remove = freqs.size() - k;
        for (int i = 0; i < to_remove; ++i) {
            ans += freqs[i];
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int minDeletion(String s, int k) {
        Map<Character, Integer> cnt = new HashMap<>();
        for (int i = 0; i < s.length(); ++i) {
            char ch = s.charAt(i);
            cnt.put(ch, cnt.getOrDefault(ch, 0) + 1);
        }

        if (cnt.size() <= k) return 0;

        List<Integer> freqs = new ArrayList<>(cnt.values());
        Collections.sort(freqs);

        int ans = 0;
        int toRemove = freqs.size() - k;
        for (int i = 0; i < toRemove; ++i) {
            ans += freqs.get(i);
        }
        return ans;
    }
}

