var minDeletion = function(s, k) {
    const cnt = {};
    for (const ch of s) {
        cnt[ch] = (cnt[ch] || 0) + 1;
    }

    const freqs = Object.values(cnt).sort((a, b) => a - b);
    if (freqs.length <= k) return 0;

    let ans = 0;
    const toRemove = freqs.length - k;
    for (let i = 0; i < toRemove; ++i) {
        ans += freqs[i];
    }
    return ans;
};
